class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0
        self.rolls_in_frame = 0
        self.first_roll = None
        self.second_roll = None
        self.game_over = False

    def roll(self, pins):
        if pins < 0:
            raise Exception("Roll cannot score negative points")
        if pins > 10:
            raise Exception("Roll cannot score more than 10 points")
        if self.game_over:
            raise Exception("Cannot roll after game is over")
        if self.frame < 9:
            self._roll_frame(pins)
        else:
            self._roll_tenth_frame(pins)

    def _roll_frame(self, pins):
        if self.rolls_in_frame == 0:
            self.first_roll = pins
            self.rolls.append(pins)
            self.rolls_in_frame = 1
            if pins == 10:
                self._advance_frame()
        else:
            if self.first_roll + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            self.rolls.append(pins)
            self._advance_frame()

    def _advance_frame(self):
        self.frame += 1
        self.rolls_in_frame = 0
        self.first_roll = None
        self.second_roll = None
        if self.frame == 10:
            self.game_over = True

    def _roll_tenth_frame(self, pins):
        if self.rolls_in_frame == 0:
            self.first_roll = pins
            self.rolls.append(pins)
            self.rolls_in_frame = 1
        elif self.rolls_in_frame == 1:
            if self.first_roll != 10 and self.first_roll + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            self.second_roll = pins
            self.rolls.append(pins)
            self.rolls_in_frame = 2
            if self.first_roll != 10 and self.first_roll + self.second_roll < 10:
                self.game_over = True
        else:
            if (
                self.first_roll == 10
                and self.second_roll != 10
                and self.second_roll + pins > 10
            ):
                raise Exception(
                    "Bonus rolls in the last frame cannot score more than 10 points"
                )
            self.rolls.append(pins)
            self.game_over = True

    def score(self):
        if not self.game_over:
            raise Exception("Cannot score an incomplete game")
        total = 0
        rolls = self.rolls
        i = 0
        for _ in range(10):
            if rolls[i] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                total += 10 + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
